import os

out_dir = "/app/output"
os.makedirs(out_dir, exist_ok=True)

css = """
:root {
  --primary: #F02D00;
  --dark: #171717;
  --light: #FFFFFF;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-300: #d1d5db;
  --gray-400: #9ca3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-800: #1f2937;
  --accent: #14b8a6; /* Teal */
  --font-sans: 'Inter', sans-serif;
  --radius: 8px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: var(--font-sans); color: var(--dark); background: var(--light); line-height: 1.5; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

/* Utilities */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.btn { display: inline-flex; align-items: center; justify-content: center; padding: 10px 20px; font-weight: 600; border-radius: 4px; transition: all 0.2s; text-align: center; }
.btn-primary { background: var(--primary); color: white; }
.btn-primary:hover { background: #d02600; }
.btn-outline { border: 1px solid var(--gray-300); color: var(--dark); }
.btn-outline:hover { background: var(--gray-50); }
.btn-dark { background: var(--dark); color: white; }
.btn-dark:hover { background: #000; }
.text-primary { color: var(--primary); }
.text-gray { color: var(--gray-500); }
.font-bold { font-weight: 700; }
.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 0.5rem; }
.gap-4 { gap: 1rem; }
.gap-6 { gap: 1.5rem; }
.gap-8 { gap: 2rem; }
.grid { display: grid; }

/* Promo Banner */
#promo-banner { background: var(--dark); color: white; padding: 12px 24px; display: flex; justify-content: center; align-items: center; position: relative; font-size: 14px; font-weight: 500; }
#promo-banner .close-btn { position: absolute; right: 24px; top: 50%; transform: translateY(-50%); color: white; }
.countdown { color: var(--accent); margin-left: 8px; font-variant-numeric: tabular-nums; }

/* Header */
header { border-bottom: 1px solid var(--gray-200); position: sticky; top: 0; background: white; z-index: 100; }
.header-inner { height: 72px; }
.logo { font-size: 24px; font-weight: 800; letter-spacing: -0.5px; }
.logo span { color: var(--primary); }
.nav-links { display: flex; gap: 24px; align-items: center; font-weight: 500; font-size: 15px; }
.nav-links a:hover { color: var(--primary); }
.search-icon { font-size: 20px; color: var(--gray-600); }

/* Footer */
footer { background: var(--dark); color: white; padding: 64px 0 32px; font-size: 14px; margin-top: 64px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 32px; margin-bottom: 48px; }
.footer-col h4 { font-size: 16px; margin-bottom: 16px; font-weight: 600; color: white; display: flex; justify-content: space-between; align-items: center; }
.footer-col ul { display: flex; flex-direction: column; gap: 12px; }
.footer-col a { color: var(--gray-400); transition: color 0.2s; }
.footer-col a:hover { color: white; }
.footer-bottom { border-top: 1px solid var(--gray-800); padding-top: 24px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 16px; color: var(--gray-400); }
.footer-bottom-links { display: flex; gap: 16px; flex-wrap: wrap; }

/* Carousel general */
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 24px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; -webkit-overflow-scrolling: touch; padding-bottom: 16px; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-item { scroll-snap-align: start; flex-shrink: 0; }
.carousel-arrow { position: absolute; top: 50%; transform: translateY(-50%); width: 48px; height: 48px; background: white; border-radius: 50%; box-shadow: var(--shadow-md); display: flex; align-items: center; justify-content: center; z-index: 10; font-size: 24px; color: var(--dark); cursor: pointer; transition: all 0.2s; border: 1px solid var(--gray-200); }
.carousel-arrow:hover { background: var(--gray-50); }
.carousel-arrow.prev { left: -24px; }
.carousel-arrow.next { right: -24px; }

/* Cards */
.course-card { border: 1px solid var(--gray-200); border-radius: var(--radius); overflow: hidden; transition: box-shadow 0.2s; display: flex; flex-direction: column; background: white; width: 300px; }
.course-card:hover { box-shadow: var(--shadow-lg); }
.course-image { height: 160px; background: var(--gray-200); position: relative; }
.course-image img { width: 100%; height: 100%; object-fit: cover; }
.badge { position: absolute; top: 12px; left: 12px; background: var(--primary); color: white; font-size: 11px; font-weight: 700; padding: 4px 8px; border-radius: 4px; text-transform: uppercase; }
.course-content { padding: 16px; flex-grow: 1; display: flex; flex-direction: column; }
.course-title { font-size: 16px; font-weight: 600; margin-bottom: 8px; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.course-instructor { font-size: 14px; color: var(--gray-500); margin-bottom: 12px; }
.course-stats { display: flex; gap: 12px; font-size: 13px; color: var(--gray-600); margin-bottom: 16px; align-items: center; }
.course-stats i { color: #f59e0b; }
.course-price-box { margin-top: auto; display: flex; align-items: center; gap: 8px; }
.price-current { font-size: 18px; font-weight: 700; color: var(--dark); }
.price-old { font-size: 14px; color: var(--gray-400); text-decoration: line-through; }
.discount-badge { font-size: 12px; color: var(--primary); font-weight: 600; background: #fee2e2; padding: 2px 6px; border-radius: 4px; }

/* Spec Card */
.spec-card { display: flex; background: var(--dark); color: white; border-radius: var(--radius); overflow: hidden; width: 100%; max-width: 800px; }
.spec-image { width: 40%; background: #333; position: relative; }
.spec-image img { width: 100%; height: 100%; object-fit: cover; opacity: 0.8; }
.spec-content { width: 60%; padding: 40px; display: flex; flex-direction: column; justify-content: center; }
.spec-label { font-size: 12px; font-weight: 700; color: var(--accent); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 16px; display: inline-block; }
.spec-title { font-size: 32px; font-weight: 800; line-height: 1.2; margin-bottom: 16px; }
.spec-desc { font-size: 16px; color: var(--gray-300); margin-bottom: 24px; line-height: 1.6; }
.spec-stats { display: flex; gap: 16px; font-size: 14px; color: var(--gray-300); margin-bottom: 32px; }
.spec-stats i { color: #f59e0b; }
.spec-price-row { display: flex; align-items: center; gap: 12px; margin-bottom: 24px; }
.spec-price-row .price-current { color: white; font-size: 24px; }

/* Project Card */
.project-card { border-radius: var(--radius); overflow: hidden; background: white; box-shadow: var(--shadow-sm); transition: transform 0.2s; margin-bottom: 24px; break-inside: avoid; }
.project-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.project-img { width: 100%; background: var(--gray-200); }
.project-info { padding: 12px; }
.project-title { font-weight: 600; font-size: 14px; margin-bottom: 4px; }
.project-author { font-size: 13px; color: var(--gray-500); }
.project-meta { display: flex; justify-content: space-between; font-size: 12px; color: var(--gray-500); margin-top: 12px; }
.project-meta div { display: flex; align-items: center; gap: 4px; }

/* Grid Layouts */
.courses-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 24px; }
.masonry-grid { column-count: 3; column-gap: 24px; }
@media (max-width: 900px) { .masonry-grid { column-count: 2; } }
@media (max-width: 600px) { .masonry-grid { column-count: 1; } }

/* Sidebar Layout */
.layout-sidebar { display: grid; grid-template-columns: 240px 1fr; gap: 48px; margin-top: 40px; }
.sidebar h3 { font-size: 16px; font-weight: 700; margin-bottom: 16px; padding-bottom: 8px; border-bottom: 1px solid var(--gray-200); }
.sidebar ul { margin-bottom: 32px; }
.sidebar li { margin-bottom: 8px; }
.sidebar a { font-size: 14px; color: var(--gray-600); display: block; padding: 4px 0; transition: color 0.2s; }
.sidebar a:hover, .sidebar a.active { color: var(--primary); font-weight: 600; }

/* Value Props */
.value-props-section { background: var(--gray-50); padding: 80px 0; }
.value-props-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 40px; }
.value-prop { text-align: center; }
.value-prop-icon { width: 64px; height: 64px; background: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 28px; color: var(--primary); margin: 0 auto 20px; box-shadow: var(--shadow-sm); }
.value-prop h3 { font-size: 18px; font-weight: 700; margin-bottom: 12px; }
.value-prop p { font-size: 15px; color: var(--gray-600); }

/* Plus Pricing */
.pricing-section { padding: 80px 0; text-align: center; }
.pricing-toggle { display: inline-flex; background: var(--gray-100); padding: 4px; border-radius: 8px; margin-bottom: 48px; }
.toggle-btn { padding: 12px 24px; font-weight: 600; font-size: 15px; border-radius: 4px; cursor: pointer; transition: all 0.2s; }
.toggle-btn.active { background: white; box-shadow: var(--shadow-sm); color: var(--dark); }
.toggle-btn.inactive { color: var(--gray-500); }
.pricing-card { max-width: 480px; margin: 0 auto; border: 2px solid var(--dark); border-radius: 12px; padding: 40px; text-align: left; position: relative; }
.pricing-badge { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: var(--accent); color: var(--dark); font-weight: 800; padding: 4px 16px; border-radius: 20px; font-size: 14px; white-space: nowrap;}
.price-display { font-size: 48px; font-weight: 800; margin: 16px 0 8px; display: flex; align-items:baseline; gap: 4px; }
.price-display span { font-size: 18px; font-weight: 500; color: var(--gray-500); }
.pricing-features { margin: 32px 0; display: flex; flex-direction: column; gap: 16px; }
.pricing-features li { display: flex; align-items: flex-start; gap: 12px; font-size: 15px; }
.pricing-features i { color: var(--primary); font-size: 20px; }

/* FAQ Accordion */
.faq-section { max-width: 800px; margin: 0 auto 80px; }
.accordion-item { border-bottom: 1px solid var(--gray-200); }
.accordion-header { width: 100%; text-align: left; padding: 24px 0; font-size: 18px; font-weight: 600; display: flex; justify-content: space-between; align-items: center; background: none; cursor: pointer;}
.accordion-header i { transition: transform 0.3s; color: var(--gray-400); }
.accordion-content { overflow: hidden; max-height: 0; transition: max-height 0.3s ease-out; }
.accordion-content-inner { padding-bottom: 24px; color: var(--gray-600); font-size: 16px; line-height: 1.6; }
.accordion-item.active .accordion-header i { transform: rotate(180deg); }
.accordion-item.active .accordion-content { max-height: 500px; }

/* Login Form */
.login-container { min-height: calc(100vh - 72px - 40px); display: flex; align-items: center; justify-content: center; padding: 40px 24px; background: var(--gray-50); }
.login-box { background: white; padding: 48px; border-radius: 12px; box-shadow: var(--shadow-lg); width: 100%; max-width: 480px; text-align: center; }
.login-box h1 { font-size: 28px; font-weight: 800; margin-bottom: 8px; }
.login-box p { color: var(--gray-500); margin-bottom: 32px; }
.social-login { display: flex; flex-direction: column; gap: 12px; margin-bottom: 24px; }
.btn-social { width: 100%; display: flex; align-items: center; justify-content: center; gap: 12px; padding: 12px; border: 1px solid var(--gray-300); border-radius: 4px; font-weight: 600; transition: all 0.2s; }
.btn-social:hover { background: var(--gray-50); }
.btn-social.facebook { background: #1877F2; color: white; border-color: #1877F2; }
.btn-social.facebook:hover { background: #166fe5; }
.divider { display: flex; align-items: center; margin: 24px 0; color: var(--gray-400); font-size: 14px; }
.divider::before, .divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.divider span { padding: 0 16px; }
.form-group { text-align: left; margin-bottom: 20px; position: relative; }
.form-group label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 8px; }
.form-control { width: 100%; padding: 12px 16px; border: 1px solid var(--gray-300); border-radius: 4px; font-family: inherit; font-size: 15px; outline: none; transition: border-color 0.2s; }
.form-control:focus { border-color: var(--primary); }
.password-toggle { position: absolute; right: 16px; top: 38px; color: var(--gray-500); cursor: pointer; font-size: 18px; }

@media (max-width: 768px) {
  .layout-sidebar { grid-template-columns: 1fr; }
  .carousel-arrow { display: none; }
  .spec-card { flex-direction: column; }
  .spec-image { width: 100%; height: 200px; }
  .spec-content { width: 100%; padding: 24px; }
  .footer-col h4 i { display: block; cursor: pointer; }
  .footer-col ul { display: none; }
  .footer-col.active ul { display: flex; }
  .nav-links { display: none; } /* Simplified mobile nav for demo */
}
@media (min-width: 769px) {
  .footer-col h4 i { display: none; }
  .footer-col ul { display: flex !important; }
}
"""

js = """
document.addEventListener('DOMContentLoaded', () => {
  // Dismiss Promo Banner
  const banner = document.getElementById('promo-banner');
  const closeBanner = document.getElementById('close-banner');
  if (closeBanner && banner) {
    closeBanner.addEventListener('click', () => {
      banner.style.display = 'none';
    });
  }

  // Countdown Timer
  const countdownEl = document.getElementById('countdown');
  if (countdownEl) {
    let hours = 23, minutes = 59, seconds = 59;
    setInterval(() => {
      seconds--;
      if (seconds < 0) { seconds = 59; minutes--; }
      if (minutes < 0) { minutes = 59; hours--; }
      countdownEl.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    }, 1000);
  }

  // Carousels
  const carousels = document.querySelectorAll('.carousel-wrapper');
  carousels.forEach(wrapper => {
    const track = wrapper.querySelector('.carousel-track');
    const prevBtn = wrapper.querySelector('.carousel-arrow.prev');
    const nextBtn = wrapper.querySelector('.carousel-arrow.next');

    if (track && prevBtn && nextBtn) {
      prevBtn.addEventListener('click', () => {
        const item = track.querySelector('.carousel-item');
        const scrollAmount = item ? item.offsetWidth + 24 : 324;
        track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
      });
      nextBtn.addEventListener('click', () => {
        const item = track.querySelector('.carousel-item');
        const scrollAmount = item ? item.offsetWidth + 24 : 324;
        track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });
    }
  });

  // Footer Accordion (Mobile)
  const footerHeaders = document.querySelectorAll('.footer-col h4');
  footerHeaders.forEach(header => {
    header.addEventListener('click', () => {
      if (window.innerWidth <= 768) {
        const col = header.parentElement;
        col.classList.toggle('active');
        const icon = header.querySelector('i');
        if (col.classList.contains('active')) {
          icon.classList.replace('ri-add-line', 'ri-subtract-line');
        } else {
          icon.classList.replace('ri-subtract-line', 'ri-add-line');
        }
      }
    });
  });

  // Plus Pricing Toggle
  const toggleMonthly = document.getElementById('toggle-monthly');
  const toggleYearly = document.getElementById('toggle-yearly');
  const priceDisplay = document.getElementById('price-display');
  const billedDisplay = document.getElementById('billed-display');
  const savingsBadge = document.getElementById('savings-badge');
  const creditsText = document.getElementById('credits-text');

  if (toggleMonthly && toggleYearly) {
    toggleMonthly.addEventListener('click', () => {
      toggleMonthly.classList.replace('inactive', 'active');
      toggleYearly.classList.replace('active', 'inactive');
      priceDisplay.innerHTML = '$33.90<span>/month</span>';
      billedDisplay.textContent = 'Billed $33.90 monthly';
      savingsBadge.style.display = 'none';
      creditsText.innerHTML = '1 Plus credit every month';
    });

    toggleYearly.addEventListener('click', () => {
      toggleYearly.classList.replace('inactive', 'active');
      toggleMonthly.classList.replace('active', 'inactive');
      priceDisplay.innerHTML = '$14.59<span>/month</span>';
      billedDisplay.textContent = 'Billed as $174.50/year';
      savingsBadge.style.display = 'block';
      savingsBadge.textContent = 'SAVE 57%';
      creditsText.innerHTML = '12 Plus credits every year';
    });
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.accordion-item');
  faqItems.forEach(item => {
    const header = item.querySelector('.accordion-header');
    header.addEventListener('click', () => {
      const isActive = item.classList.contains('active');
      faqItems.forEach(i => i.classList.remove('active'));
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Login Password Toggle
  const passToggle = document.getElementById('password-toggle');
  const passInput = document.getElementById('password');
  if (passToggle && passInput) {
    passToggle.addEventListener('click', () => {
      if (passInput.type === 'password') {
        passInput.type = 'text';
        passToggle.classList.replace('ri-eye-off-line', 'ri-eye-line');
      } else {
        passInput.type = 'password';
        passToggle.classList.replace('ri-eye-line', 'ri-eye-off-line');
      }
    });
  }

  // Login Form Submit
  const loginForm = document.getElementById('login-form');
  if (loginForm) {
    loginForm.addEventListener('submit', (e) => {
      e.preventDefault();
      // Simulation: reset form
      loginForm.reset();
    });
  }

  // Sidebar Filtering (Simulation)
  const sidebarLinks = document.querySelectorAll('.sidebar a');
  if (sidebarLinks.length > 0) {
    sidebarLinks.forEach(link => {
      link.addEventListener('click', (e) => {
        e.preventDefault();
        sidebarLinks.forEach(l => l.classList.remove('active'));
        link.classList.add('active');

        const grid = document.querySelector('.courses-grid');
        if(grid) {
          grid.style.opacity = '0.5';
          setTimeout(() => {
            grid.style.opacity = '1';
          }, 300);
        }
      });
    });
  }

  // Projects Filtering (Simulation)
  const projectFilters = document.querySelectorAll('.project-filters select');
  if (projectFilters.length > 0) {
    projectFilters.forEach(filter => {
      filter.addEventListener('change', () => {
        const grid = document.querySelector('.masonry-grid');
        if(grid) {
          grid.style.opacity = '0.5';
          setTimeout(() => {
            grid.style.opacity = '1';
          }, 300);
        }
      });
    });
  }
});
"""

